  ((SELECT id FROM actor WHERE russian_name = 'Томас Митчелл' AND (original_name = 'Thomas Mitchell' OR (original_name IS NULL AND 'Thomas Mitchell' IS NULL))), (SELECT id FROM film WHERE title = 'Эта замечательная жизнь' AND year = 1947), 'Uncle Billy', NULL),
