) AS t(actor_id, film_id, character, description)
WHERE actor_id IS NOT NULL AND film_id IS NOT NULL
AND NOT EXISTS (
  SELECT 1 FROM actor_in_film aif
  WHERE aif.actor_id = t.actor_id
    AND aif.film_id = t.film_id
);

COMMIT;

INSERT INTO film_feedback (user_id, film_id, title, text, rating)
SELECT 
    user_id::uuid,
    'b5de9741-3728-4477-a43a-8dfbf731d736',
    title,
    text,
    rating
FROM (VALUES
    ('a1b2c3d4-e5f6-7890-abcd-ef1234567890', 'Ностальгия по детству', 'Отличный фильм для подростков! Хилари Дафф просто очаровательна.', 8),
    ('b2c3d4e5-f6a7-8901-bcde-f23456789012', 'Милая комедия', 'Легкий и веселый фильм, идеально подходит для семейного просмотра.', 9),
    ('c3d4e5f6-a7b8-9012-cdef-345678901234', 'Хороший подростковый фильм', 'Не шедевр, но смотреть приятно. Итальянские пейзажи прекрасны.', 7),
    ('d4e5f6a7-b8c9-0123-def4-456789012345', 'Весело и позитивно', 'Простенький сюжет, но много хорошего настроения. Рим показан красиво.', 7),
    ('e5f6a7b8-c9d0-1234-ef56-567890123456', 'Детская классика', 'Вырос на этом фильме! До сих пор смотрю с удовольствием.', 10)
) AS vals(user_id, title, text, rating)
WHERE EXISTS (SELECT 1 FROM film WHERE id = 'b5de9741-3728-4477-a43a-8dfbf731d736');

INSERT INTO film_feedback (user_id, film_id, title, text, rating)
SELECT user_id::uuid, '7fc96be9-ec6f-4778-9943-a87d61f02887', title, text, rating FROM (VALUES
    ('b4c5d6e7-f8a9-0123-4f56-456789abcdef', 'Отличная семейная комедия', 'Забавный и поучительный фильм. Шайа ЛаБаф молодцом!', 8),
    ('c5d6e7f8-a9b0-1234-5f67-56789abcdef0', 'Увлекательная история', 'Сюжет с неожиданными поворотами. Хорошо показана дружба.', 7),
    ('d6e7f8a9-b0c1-2345-6f78-6789abcdef01', 'Смешной и трогательный', 'Сочетание юмора и драмы идеальное. Рекомендую детям.', 8),
    ('e7f8a9b0-c1d2-3456-7f89-789abcdef012', 'Немного затянуто', 'Хорошая идея, но некоторые сцены можно было сократить.', 6),
