) AS vals(user_id, title, text, rating) WHERE EXISTS (SELECT 1 FROM film WHERE id = '53666f9d-bc9f-4c98-8224-c3923b33ee19');

INSERT INTO film_feedback (user_id, film_id, title, text, rating)
SELECT user_id::uuid, 'c0caad3d-cf0c-4407-a336-377aabe69128', title, text, rating FROM (VALUES
    ('f6a7b8c9-d0e1-2345-f678-678901234567', 'Умный триллер', 'Интеллектуальный сюжет с неожиданной развязкой. Эдвард Бернс отлично сыграл.', 8),
    ('a7b8c9d0-e1f2-3456-789a-789012345678', 'Запутанная история', 'Много поворотов, сложно предугадать концовку. Интересно следить за аферистами.', 7),
    ('b8c9d0e1-f2a3-4567-89ab-890123456789', 'Стильный фильм', 'Атмосфера 2000-х передана прекрасно. Хороший саундтрек и операторская работа.', 8),
    ('f2a3b4c5-d6e7-8901-2f34-23456789abcd', 'Средненько', 'Неплохой фильм, но ничего особенного. Забывается быстро.', 5),
