) AS vals(user_id, title, text, rating) WHERE EXISTS (SELECT 1 FROM film WHERE id = 'c0caad3d-cf0c-4407-a336-377aabe69128');

INSERT INTO film_feedback (user_id, film_id, title, text, rating)
