) AS t(actor_id, film_id, character, description)
WHERE actor_id IS NOT NULL AND film_id IS NOT NULL
AND NOT EXISTS (
  SELECT 1 FROM actor_in_film aif
  WHERE aif.actor_id = t.actor_id
    AND aif.film_id = t.film_id
);

