INSERT INTO film (id, title, original_title, cover, poster,
                 short_description, description, age_category,
                 budget, worldwide_fees, year, country_id, genre_id,
                 slogan, duration, release_date)
VALUES
  ('e4482ab6-9f0e-4da7-989a-e8466ed3dbba', 'Телохранитель', 'Yojinbo', 'films/pic221.webp', 'posters/pic221.webp', 'В некий японский городок приходит самурай. Самурай выглядит совершенно не по-самурайски: плохо пострижен, не причёсан. А в городе две организованные преступные группировки, созданные местечковыми олигархами из лиц, находящихся под следствием и в розыске, терроризируют жителей городка, жестоко страдающих от бандитского беспредела. Проявляя недюжинную оперативную смекалку и мастерски работая мечом, попеременно нанимаясь телохранителем то в одну, то в другую банду, самурай искусно сокращает пого...', 'В некий японский городок приходит самурай. Самурай выглядит совершенно не по-самурайски: плохо пострижен, не причёсан. А в городе две организованные преступные группировки, созданные местечковыми олигархами из лиц, находящихся под следствием и в розыске, терроризируют жителей городка, жестоко страдающих от бандитского беспредела. Проявляя недюжинную оперативную смекалку и мастерски работая мечом, попеременно нанимаясь телохранителем то в одну, то в другую банду, самурай искусно сокращает поголовье уродов, попутно решая собственные задачи.', '16+', 200000000, 1000000000, 1961, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a15', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Better if all these men were dead. Think about it!', 110, '1961-06-01'),
  ('9bfb9e82-f4ed-472f-b65e-3bfddae2171c', 'Гроздья гнева', 'The Grapes of Wrath', 'films/pic222.webp', 'posters/pic222.webp', 'Семья разорившихся фермеров едет в Калифорнию за лучшей долей. Оскароносная экранизация великого романа', 'После тюремного срока за убийство Том Джоад возвращается на своё семейное ранчо, которое к тому времени полностью разорилось и пребывает в запустении. В отсутствие какой-либо перспективы найти работу в засушливой Оклахоме вся семья собирает свой скарб и отправляется на «землю обетованную» - в Калифорнию. 
Но трудный путь и тяжкие условия не приносят искомой надежды, и даже единство семьи подвергается испытаниям.', '18+', 1000000, 2000000, 1940, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'The thousands who have read the book will know why WE WILL NOT SELL ANY CHILDREN TICKETS to see this picture!', 129, '1940-06-01'),
  ('ff63d78b-de4e-433c-9dc0-84193f26d59c', 'Звёздные войны: Эпизод 6 – Возвращение Джедая', 'Star Wars: Episode VI - Return of the Jedi', 'films/pic223.webp', 'posters/pic223.webp', 'Настал момент решающей битвы с Императором и Дартом Вейдером. Эпический финал первой трилогии Джорджа Лукаса', 'В шестом эпизоде «Звездных войн» Дарт Вейдер создает вторую «Звезду Смерти». Он объединяет все силы зла, чтобы с помощью этого смертоносного оружия нанести последний сокрушительный удар по повстанцам и их союзникам.

Люк Скайуокер вместе с принцессой Лейей и верными дроидами R2D2 и C-3PO отправляется спасать своего друга Хана Соло, который попал в плен к отвратительному Джаббе Хатту - могущественному повелителю преступников.

Повстанцы высаживаются на планету Эндор, чтобы оттуда вместе с Люком и его отрядом предпринять последнюю атаку на Имперский флот, атаку, от которой зависит судьба Галактики. В этом эпизоде Люк Скайуокер и Дарт Вейдер встречаются в последний раз... ибо из поединка между отцом и сыном живым выйдет только один...', '12+', 10000000, 5000000, 1983, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '7f2d3f26-fff8-fdfa-2ffb-1b1f9f5f71f3', 'The Saga Continues', 131, '1983-06-01'),
  ('910316da-9140-4acb-977c-67e881ebb483', 'Форрест Гамп', 'Forrest Gump', 'films/pic224.webp', 'posters/pic224.webp', 'Полувековая история США глазами чудака из Алабамы. Абсолютная классика Роберта Земекиса с Томом Хэнксом', 'Сидя на автобусной остановке, Форрест Гамп — не очень умный, но добрый и открытый парень — рассказывает случайным встречным историю своей необыкновенной жизни.

С самого малолетства парень страдал от заболевания ног, соседские мальчишки дразнили его, но в один прекрасный день Форрест открыл в себе невероятные способности к бегу. Подруга детства Дженни всегда его поддерживала и защищала, но вскоре дороги их разошлись.', '18+', 80000000, 400000000, 1994, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Мир уже никогда не будет прежним, после того как вы увидите его глазами Форреста Гампа', 142, '1994-06-01'),
  ('d7e0d44f-7046-48d0-b08d-0ed59f3a13d8', 'Мышьяк и старые кружева', 'Arsenic and Old Lace', 'films/pic225.webp', 'posters/pic225.webp', 'Не зря возражал отец Элейн против брака его дочери с Мортимером в канун Хэллоуина. Всё сразу пошло наперекосяк. Молодожёны переезжают в большой мрачный дом семьи Брюстер в Бруклине, неподалёку от старинного кладбища. В доме живут две милые старые тётушки Мортимера и абсолютно сумасшедший двоюродный брат, считающий себя президентом Рузвельтом.

Неожиданно появляется ещё один брат – убийца-маньяк, только что сбежавший из тюрьмы. Может, хотя бы старушки нормальны? Увы…', 'Не зря возражал отец Элейн против брака его дочери с Мортимером в канун Хэллоуина. Всё сразу пошло наперекосяк. Молодожёны переезжают в большой мрачный дом семьи Брюстер в Бруклине, неподалёку от старинного кладбища. В доме живут две милые старые тётушки Мортимера и абсолютно сумасшедший двоюродный брат, считающий себя президентом Рузвельтом.

Неожиданно появляется ещё один брат – убийца-маньяк, только что сбежавший из тюрьмы. Может, хотя бы старушки нормальны? Увы…', '12+', 100000000, 300000000, 1944, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'She Passed Out On Cary ! No Wonder . . . She''s just discovered his favorite aunts have poisoned their 13th gentleman friend !', 118, '1944-06-01'),
  ('67a02fbc-b906-4382-aa8e-2dc729394608', 'Дикая банда', 'The Wild Bunch', 'films/pic226.webp', 'posters/pic226.webp', 'Стареющие преступники собираются на последнее дело. Революционно кровавый и циничный вестерн Сэма Пекинпы', 'Начало XX века. Эпоха Дикого Запада подходит к концу. Во время ограбления офиса железной дороги банда под предводительством стареющего Пайка Бишопа попадает в засаду. Завязывается ожесточённая перестрелка, в которой погибают несколько бандитов и много местных жителей. С трудом вырвавшись из ловушки и оставшись без награбленного, Бишоп и четверо оставшихся в живых подельников решают провернуть последнее дело в Мексике, чтобы сорвать большой куш и уйти на покой. Однако всё идёт не совсем по плану, а в погоню за бандитами уже отправлен отряд стрелков во главе с бывшим членом банды Диком Торнтоном.', '18+', 5000000, 15000000, 1969, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Born too late for their own times. Uncommonly significant for ours', 145, '1969-06-01'),
  ('00e7e8bc-bf59-449f-944e-ef1026393012', 'Непрощенный', 'Unforgiven', 'films/pic227.webp', 'posters/pic227.webp', 'Бывший убийца снова берется за оружие ради своих детей. Оскароносный драматический вестерн Клинта Иствуда', 'История Уильяма Манни — бывшего хладнокровного убийцы, нашедшего в себе силы покончить с грязным ремеслом. Он стал фермером, завёл семью. Но все складывается совсем не так, как ему хотелось.', '18+', 50000000, 50000000, 1992, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'It''s a hell of a thing, killing a man', 131, '1992-06-01'),
  ('6d09e11e-e1fa-42c7-a99e-58ce7925f9cf', 'Рождественская история', 'A Christmas Story', 'films/pic228.webp', 'posters/pic228.webp', 'Индиана, 1940 год. Девятилетний Ральфи мечтает об идеальном рождественском подарке - настоящей двухсотзарядной пневматической винтовке Красного Наездника.

Ворчливый папаша и заботливая мамочка, естественно, против, полагая, что их драгоценный сынуля может себя покалечить! И тогда Ральфи решает обратиться за помощью к самому Санта-Клаусу.', 'Индиана, 1940 год. Девятилетний Ральфи мечтает об идеальном рождественском подарке - настоящей двухсотзарядной пневматической винтовке Красного Наездника.

Ворчливый папаша и заботливая мамочка, естественно, против, полагая, что их драгоценный сынуля может себя покалечить! И тогда Ральфи решает обратиться за помощью к самому Санта-Клаусу.', '12+', 300000000, 150000000, 1983, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'adf056b9-c2f5-90ad-f5fe-ffe8fc2baff0', '''Tis better to give than to receive', 93, '1983-06-01'),
  ('22987807-9988-4167-9a7b-f5870ef31a83', 'Ночь охотника', 'The Night of the Hunter', 'films/pic229.webp', 'posters/pic229.webp', 'Мальчику Джону и его сестричке Пэрл «посчастливилось» увидеть, как их отца увозит полиция, схватив его за ограбление и убийство двух человек. Отца приговаривают к смерти и вешают, в наследство детям остаются украденные деньги, которые отец спрятал, взяв с Джона и Пэрл слово, что они никому не расскажут о тайнике, даже матери. В тюрьме он познакомился с проповедником Гарри Пауэллом, а на деле — безжалостным убийцей, помешанном на религии, со словами «любовь» и «ненависть», вытатуированными на ...', 'Мальчику Джону и его сестричке Пэрл «посчастливилось» увидеть, как их отца увозит полиция, схватив его за ограбление и убийство двух человек. Отца приговаривают к смерти и вешают, в наследство детям остаются украденные деньги, которые отец спрятал, взяв с Джона и Пэрл слово, что они никому не расскажут о тайнике, даже матери. В тюрьме он познакомился с проповедником Гарри Пауэллом, а на деле — безжалостным убийцей, помешанном на религии, со словами «любовь» и «ненависть», вытатуированными на пальцах рук. Пауэлл решает добраться до тайника и для этого женится на доверчивой вдове.', NULL, 80000000, 240000000, 1955, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'The scenes...the story...The stars BUT ABOVE ALL - THE SUSPENSE!', 92, '1955-06-01'),
  ('0e7f9e02-fc22-444d-bbde-f09d0eff4474', 'Почти знаменит', 'Almost Famous', 'films/pic230.webp', 'posters/pic230.webp', 'Юный журналист сопровождает рок-группу в турне. Теплое драмеди о взрослении в 1970-х, «Оскар» за сценарий', 'Сан-Диего, 1973 год. 15-летний вундеркинд Уильям Миллер, фанат рок-музыки, способный писать крутые музыкальные статьи, становится самым молодым корреспондентом журнала Rolling Stone и отправляется в тур с группой Stillwater.', '18+', 300000000, 2400000000, 2000, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Experience it. Enjoy it. Just don''t fall for it', 123, '2000-06-01'),
  ('99dfc7ab-fd8f-4eb9-b875-97046c495fb8', 'Молодой Франкенштейн', 'Young Frankenstein', 'films/pic231.webp', 'posters/pic231.webp', 'Молодой доктор Фредерик Франкентшейн, внук Виктора Франкенштейна, невероятно стыдящийся близкого родства со знаменитым бароном, отправляется в Трансильванию, чтобы вступить во владение замком, оставленным дедом ему в наследство. Фредерик долгие годы был уверен, что работа его дедушки — полнейшая ерунда, но найдя в замке книгу с описанием его экспериментов и внимательно изучив её, молодой человек резко меняет мнение.', 'Молодой доктор Фредерик Франкентшейн, внук Виктора Франкенштейна, невероятно стыдящийся близкого родства со знаменитым бароном, отправляется в Трансильванию, чтобы вступить во владение замком, оставленным дедом ему в наследство. Фредерик долгие годы был уверен, что работа его дедушки — полнейшая ерунда, но найдя в замке книгу с описанием его экспериментов и внимательно изучив её, молодой человек резко меняет мнение.', '16+', 200000000, 400000000, 1974, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'adf056b9-c2f5-90ad-f5fe-ffe8fc2baff0', 'The scariest comedy of all time!', 108, '1974-06-01'),
  ('f1b42972-79af-408f-bee1-966228de2fe1', 'Унесённые ветром', 'Gone with the Wind', 'films/pic232.webp', 'posters/pic232.webp', 'Интриги, убийство, любовь — на фоне Гражданской войны в США. 8 «Оскаров»', 'Могучие ветры Гражданской войны в один миг уносят беззаботную юность южанки Скарлетт О`Хара, когда привычный шум балов сменяется грохотом канонад на подступах к родному дому. Для молодой женщины, вынужденной бороться за новую жизнь на разоренной земле, испытания и лишения становятся шансом переосмыслить идеалы, обрести веру в себя и найти настоящую любовь.', '12+', 10000000, 30000000, 1939, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'The most magnificent picture ever!', 222, '1939-06-01'),
  ('cab65861-355a-4028-a972-0b9ce3dfde2c', 'Лагерь для военнопленных № 17', 'Stalag 17', 'films/pic233.webp', 'posters/pic233.webp', 'Когда двое сбежавших американских заключённых Второй мировой были убиты, немецкий военнопленный, спекулянт лагерных казарм, Джей Джей Сефтон стал подозреваться в доносе.', 'Когда двое сбежавших американских заключённых Второй мировой были убиты, немецкий военнопленный, спекулянт лагерных казарм, Джей Джей Сефтон стал подозреваться в доносе.', NULL, 150000000, 750000000, 1952, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Hilarious, heart-tugging! You''ll laugh...you''ll cry...you''ll cheer William Holden in his great Academy Award role! (from reissue print ad)', 115, '1952-06-01'),
  ('a98774c5-8263-496f-b520-5b2d273372a8', 'Корпорация монстров', 'Monsters, Inc.', 'films/pic234.webp', 'posters/pic234.webp', 'В мире монстров есть такая работа — пугать человеческих детей. Смешной мультфильм Pixar про жизнь страшилищ', 'Склизкий гад в сливном бачке, мохнатый зверь, похожий на чудовище из «Аленького цветочка», гигантские мокрицы под кроватью — все они существуют на самом деле. Все, что им нужно — пугать детей, потому что из детских криков они получают электричество.
Полнометражный мультфильм рассказывает о кризисах в мире монстров, их жизни. Но однажды вся мирная жизнь монстров оказывается под угрозой: в их мир попадает ребенок. А с детьми столько хлопот, что они могут довести даже монстров.', '0+', 80000000, 240000000, 2001, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '0ac6bc1f-f8f1-f6f3-fbf4-4f4e2f8f04f6', 'We Think They Are Scary, But Really We Scare Them!', 92, '2001-06-01'),
  ('ba50fed5-4930-4c17-96ff-5dd366123c7b', 'Бильярдист', 'The Hustler', 'films/pic235.webp', 'posters/pic235.webp', 'Бильярдист и кидала Эдди Фелсон вместе с напарником действуют по проверенной схеме. Сначала Эдди позволяет противнику выигрывать, потом взвинчивает ставки и обирает соперника до нитки. Вскоре Эдди решает бросить вызов одному из сильнейших бильярдистов страны по прозвищу Толстяк Миннесота.', 'Бильярдист и кидала Эдди Фелсон вместе с напарником действуют по проверенной схеме. Сначала Эдди позволяет противнику выигрывать, потом взвинчивает ставки и обирает соперника до нитки. Вскоре Эдди решает бросить вызов одному из сильнейших бильярдистов страны по прозвищу Толстяк Миннесота.', '16+', 200000000, 400000000, 1961, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Trapped by the underworld . . . they risked love and fortune in a desperate gamble!', 134, '1961-06-01'),
  ('933a6f79-4716-4c62-aaa9-a14008cf0e49', 'На Западном фронте без перемен', 'All Quiet on the Western Front', 'films/pic236.webp', 'posters/pic236.webp', 'Из школьных классов — в окопы и под пули. Первая экранизация главного антивоенного романа XX века', 'Рассказ о простых немецких школьниках старших классов, которые под действием патриотической пропаганды идут на войну, принимая её как игру, и не знают, что впереди их ждет только смерть.', '18+', 200000000, 400000000, 1930, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'At last....the motion picture!', 136, '1930-06-01'),
  ('b1654a4d-404d-45b0-af96-fcb91f3a6a1a', 'Разговор', 'The Conversation', 'films/pic237.webp', 'posters/pic237.webp', 'Гарри Коул — лучший на Западном побережье эксперт по прослушивающим устройствам. Записав по заказу крупного бизнесмена беседу некой парочки, гуляющей по площади, Коул нарушает свое главное правило — не совать нос в дела заказчика — и пытается предотвратить убийство, которое, как ему кажется, вот-вот должно произойти.', 'Гарри Коул — лучший на Западном побережье эксперт по прослушивающим устройствам. Записав по заказу крупного бизнесмена беседу некой парочки, гуляющей по площади, Коул нарушает свое главное правило — не совать нос в дела заказчика — и пытается предотвратить убийство, которое, как ему кажется, вот-вот должно произойти.', '16+', 20000000, 200000000, 1974, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Harry Caul will go anywhere to bug a private conversation.', 113, '1974-06-01'),
  ('b5470bd9-1640-4859-8252-783605ecf7b4', 'Быть Джоном Малковичем', 'Being John Malkovich', 'films/pic238.webp', 'posters/pic238.webp', 'Тихому лузеру выпадает шанс побывать в голове у кинозвезды. Абсурдистская сатира по сценарию Чарли Кауфмана', 'Кукольник-неудачник по имени Шварц устраивается на работу в странную и невероятно тесную контору. В своем кабинете новоиспеченный клерк Крэйг обнаруживает крошечную потайную дверцу. Удивлению не было границ, когда он обнаружил, что за дверцей скрыт ход... в мозг голливудской звезды Джона Малковича! И тогда предприимчивый кукловод решает организовать доходное предприятие по организации экскурсий в голову звезды для всех желающих.', '18+', 150000000, 150000000, 1999, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Be All That Someone Else Can Be', 113, '1999-06-01'),
  ('33b601e4-acd0-4e08-bdba-d1d5878f72ec', 'Поговори с ней', 'Hable con ella', 'films/pic239.webp', 'posters/pic239.webp', 'Мужчины знакомятся в клинике, где они навещают впавших в кому любимых. Оскароносная драма Педро Альмодовара', 'В поисках интересного персонажа для статьи журналист Марко встречается со знаменитой женщиной-тореро Лидией. Их знакомство перерастает в страстную любовь, но все надежды рушит трагедия на корриде: удар разъяренного быка повергает Лидию в кому. Проводя дни и ночи в больнице, Марко знакомится с медбратом Бениньо. Он не первый год заботится о впавшей в кому Алисии, которую страстно любит, не надеясь на взаимность.
Схожие судьбы объединяют мужчин, но Бениньо счастлив, а Марко страдает, будучи не в силах выразить Лидии свои чувства. Видя отчаяние Марко, Бениньо дает ему совет: «Поговори с ней». Теперь только сокровенные разговоры связывают любимых, и может быть, простые слова однажды сотворят чудо, на которое так надеются Марко и Бениньо…', '18+', 5000000, 40000000, 2002, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', NULL, 112, '2002-06-01'),
  ('2f8f17aa-7dc1-4b92-921b-dc3be131a60a', 'Человек-слон', 'The Elephant Man', 'films/pic240.webp', 'posters/pic240.webp', 'Черно-белый шедевр Дэвида Линча. Билеты  — на Кинопоиске!', 'Доктор Тривз находит Джона Меррика в шоу уродцев. Внешность его настолько ужасающая, что ему приходится носить просторное одеяние, чтобы никто не увидел его пугающих наростов по всему телу. Забрав Меррика в больницу после очередного избиения хозяином, Тривз с удивлением обнаруживает в нем человека интеллектуально развитого и духовного.', '18+', 50000000, 150000000, 1980, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Реальная история о мужестве и человеческом достоинстве', 125, '1980-06-01'),
  ('c72a795c-6ad8-4df4-814c-74395e0b4c4d', 'Торжество', 'Festen', 'films/pic241.webp', 'posters/pic241.webp', 'В шикарном загородном особняке намечается торжество. На юбилей почтенного отца большого семейства съезжаются дети и родственники. В зале накрыт изумительный стол, откупорены изысканные вина. За столом нет только одной из дочерей юбиляра, покончившей с собой при таинственных обстоятельствах. Праздник начинается. Старший сын произносит первый тост. Никто не подозревает, что собравшимся нарядным гостям предстоит услышать шокирующую и жуткую правду...', 'В шикарном загородном особняке намечается торжество. На юбилей почтенного отца большого семейства съезжаются дети и родственники. В зале накрыт изумительный стол, откупорены изысканные вина. За столом нет только одной из дочерей юбиляра, покончившей с собой при таинственных обстоятельствах. Праздник начинается. Старший сын произносит первый тост. Никто не подозревает, что собравшимся нарядным гостям предстоит услышать шокирующую и жуткую правду...', '18+', 150000000, 450000000, 1998, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Every family has a secret.', 101, '1998-06-01'),
  ('6ca4a5ec-39c4-4d86-a11a-0120c110f3e8', 'Малхолланд Драйв', 'Mulholland Dr.', 'films/pic242.webp', 'posters/pic242.webp', 'Случайная авария спасает девушку от смерти, но забирает память. Триллер Дэвида Линча о поиске собственного «я»', 'Загадочная девушка, после автомобильной аварии страдающая потерей памяти, выбирает себе имя Рита с рекламного плаката к фильму с Ритой Хейворт и пытается начать новую жизнь в Голливуде. Но тайны прошлого неотступно преследуют ее.

Кто были те двое мужчин, что сидели в одной машине с ней и погибли в аварии? Почему полиция подозревает, что она была ими похищена? И случайно ли в ее жизни появляется новая подруга, начинающая актриса Бетти?', '18+', 10000000, 10000000, 2001, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Beware what you dream for...', 147, '2001-06-01'),
  ('f84f53f9-3048-4d22-900d-7564eb6b465b', 'Свой человек', 'The Insider', 'films/pic243.webp', 'posters/pic243.webp', 'Реальная история биохимика, раскрывшего тайны табачных компаний. Прекрасный каст, семь номинаций на «Оскар»', 'Джеффри Уайгэнда увольняют с поста вице-президента крупнейшей табачной компании за то, что он протестует против использования в табачной продукции компонента, вызывающего у курильщиков наркотическую зависимость. Лоуэлл Бергман, продюсер популярного телешоу, узнает об этом и убеждает Уайгэнда выступить с разоблачительным интервью по телевидению...

Естественно, это очень не нравится столпам табачной индустрии, заверяющих в безвредности производимой продукции. Олигархи принимают самые суровые меры, чтобы информация не стала достоянием гласности. От Уайгэнда уходит жена, Лоуэлла Бергмана отправляют в отпуск. Там, где задействованы большие деньги, бесполезно бороться за справедливость, но Лоуэлл и Уайгэнд не прекращают борьбу.', '18+', 200000000, 2000000000, 1999, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Two men driven to tell the truth... whatever the cost', 157, '1999-06-01'),
  ('3942d773-d057-4c62-ad6c-47f265f005b2', 'Взвод', 'Platoon', 'films/pic244.webp', 'posters/pic244.webp', 'В сентябре 1967 года куда-то в приграничный район между Вьетнамом и Камбоджей прибыл рядовой 25-го пехотного полка Крис Тэйлор. Прибыл, чтобы своими глазами увидеть, как выглядит подлинный ад. Не потусторонний, вымышленный, сочинённый писателями или художниками, а натуральный, вполне земной ад, на территории которого схлестнулись друг с другом сержант Боб Барнс и сержант Илайес Гродин. Они тоже думали, что будут воевать с партизанами-вьетконговцами, но оказалось, что иногда приходится драться...', 'В сентябре 1967 года куда-то в приграничный район между Вьетнамом и Камбоджей прибыл рядовой 25-го пехотного полка Крис Тэйлор. Прибыл, чтобы своими глазами увидеть, как выглядит подлинный ад. Не потусторонний, вымышленный, сочинённый писателями или художниками, а натуральный, вполне земной ад, на территории которого схлестнулись друг с другом сержант Боб Барнс и сержант Илайес Гродин. Они тоже думали, что будут воевать с партизанами-вьетконговцами, но оказалось, что иногда приходится драться со своими.', '16+', 1000000, 8000000, 1986, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'The first casualty of war is innocence', 120, '1986-06-01'),
  ('8a62d3af-ca25-4089-bf7d-2af74f69a1ea', 'Однажды в Америке', 'Once Upon a Time in America', 'films/pic245.webp', 'posters/pic245.webp', 'Мальчишки становятся гангстерами. Классический криминальный эпос Серджио Леоне', 'В бурные двадцатые годы, когда Америка веселилась под звуки джаза, и каждый бродяга мечтал стать миллионером, в трущобах Нью-Йорка встретились несколько отчаянных парней. Убирая с дороги конкурентов, безжалостно карая предателей и нагло проворачивая хитроумные аферы, они стали королями преступного мира золотой эры «сухого закона». Они поклялись отдать жизнь друг за друга, зная, что самое главное для них — это дружба, долг и справедливость — не утопить в реках крови и бездонном океане денег. Спустя много лет судьба жестоко обошлась с легендарными гангстерами, заставив их исполнить свою клятву. Это случилось однажды в Америке…', '18+', 150000000, 75000000, 1983, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'As boys, they made a pact to share their fortunes, their loves, their lives. As men, they shared a dream to rise from poverty to power.  Forging an empire built on greed, violence and betrayal, their ', 229, '1983-06-01'),
  ('1de04839-842b-4771-8151-4fdefccf50c8', 'Его девушка Пятница', 'His Girl Friday', 'films/pic246.webp', 'posters/pic246.webp', 'Редактор пытается любой ценой удержать бывшую жену-журналистку. Классика романтической комедии с Кэри Грантом', 'Уолтер Берне — главный редактор газеты, Хильди Джонсон — его бывшая жена и лучший репортер. Однажды она сообщает Уолтеру, что выходит замуж и увольняется. Уолтер все еще любит Хильди, да и лучшего сотрудника терять не хочет, поэтому он дает ей последнее задание — взять интервью у приговоренного к смерти Эрла Уильямса. Это будет ее лучший репортаж, вершина карьеры.', '18+', 5000000, 50000000, 1939, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'The raciest love battle in years! A wild, witty whirlwind of hysterics..! (Print Ad-Meriden Daily Journal, ((Meriden, Conn.)) 21 February 1940)', 92, '1939-06-01'),
  ('8888c29b-cc37-4d64-9ee2-bfba216a033e', 'Крепкий орешек', 'Die Hard', 'films/pic247.webp', 'posters/pic247.webp', 'Полицейский в одиночку освобождает захваченный террористами небоскреб. Эталонный боевик с Брюсом Уиллисом', 'В суперсовременном небоскребе Лос-Анджелеса полицейский Джон Макклейн ведет смертельную схватку с бандой политических террористов, взявших в заложники два десятка человек, в число которых попадает и его жена. Началось все с того, что парень приехал в город к жене, оказался на рождественском приеме, а кончилось настоящей войной...', '18+', 10000000, 100000000, 1988, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', '40 Storeys High - with Suspense, Excitement and Adventure on every level!', 133, '1988-06-01'),
  ('65cafd4e-7dbd-4ae1-94ae-1116c5a5a68e', 'Индиана Джонс и последний крестовый поход', 'Indiana Jones and the Last Crusade', 'films/pic248.webp', 'posters/pic248.webp', 'Неутомимый археолог разыскивает Святой Грааль. Шляпа, хлыст, змеи и Шон Коннери в роли Генри Джонса', 'На этот раз бесстрашный Индиана разыскивает самую таинственную реликвию в истории человечества — Святой Грааль. В этом археологу помогает его отец, профессор Джонс старший. Теперь под бдительным оком своего отца Индиане предстоит совершить много благородных подвигов и потрясающих открытий. В новых странствиях храброму археологу доведется добыть чашу, которую держал в руках Иисус Христос и получить автограф… самого Адольфа Гитлера.', '16+', 1000000, 5000000, 1989, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '1bd7cd20-f9f2-f7f4-fcf5-5f5f3f9f15f7', 'The man with the hat is back. And this time, he''s bringing his Dad', 127, '1989-06-01'),
  ('09306db4-93b1-4bb4-9148-2323e4e3da98', 'Великая иллюзия', 'La grande illusion', 'films/pic249.webp', 'posters/pic249.webp', 'Французский лейтенант сбегает из немецкого плена. Жан Габен в драме о бессмысленности и беспощадности войны', 'Первая мировая война. Самолет французских летчиков Морешаля и Больде сбит немецким асом фон Рауффенштайном, но оба пилота остались живы и попали в лагерь для военнопленных. Там же находятся несколько британских офицеров, с которыми новички объединяются в работе над тоннелем для побега.
После победы французов на Западном фронте Морешаля, Болдье и остальных французских военнопленных переводят в другую тюрьму, где комендантом назначен их «старый знакомый» фон Рауффенштайн. Комендант тепло встречает французов, замечая, что из «его» тюрьмы побег невозможен...', '12+', 300000000, 1500000000, 1937, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a11', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'A Great Drama of Human Emotions', 114, '1937-06-01'),
  ('ad7cde7a-dc73-4298-9627-b2c6e5b75f46', 'Гладиатор', 'Gladiator', 'films/pic250.webp', 'posters/pic250.webp', 'Отважный генерал, ставший рабом, мстит империи. Культовая историческая драма Ридли Скотта с пятью «Оскарами»', 'Римская империя. Бесстрашного и благородного генерала Максимуса боготворят солдаты, а старый император Марк Аврелий безгранично доверяет ему и относится как к сыну. Однако опытный воин, готовый сразиться с любым противником в честном бою, оказывается бессильным перед коварными придворными интригами. Коммод, сын Марка Аврелия, убивает отца, который планировал сделать преемником не его, а Максимуса, и захватывает власть. Решив избавиться от опасного соперника, который к тому же отказывается присягнуть ему на верность, Коммод отдаёт приказ убить Максимуса и всю его семью. Чудом выжив, но не сумев спасти близких, Максимус попадает в плен к работорговцу, который продаёт его организатору гладиаторских боёв Проксимо. Так легендарный полководец становится гладиатором. Но вскоре ему представится шанс встретиться со своим смертельным врагом лицом к лицу.', '18+', 20000000, 10000000, 2000, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Генерал, ставший рабом. Раб, ставший гладиатором. Гладиатор, бросивший вызов империи', 155, '2000-06-01'),
  ('4a826ded-8107-4e9c-8383-b976902c2968', 'Спартак', 'Spartacus', 'films/pic251.webp', 'posters/pic251.webp', 'Гладиатор возглавил восстание рабов против загнивающего Рима. Классика от Стэнли Кубрика с четырьмя «Оскарами»', 'История гладиатора Спартака, его возлюбленной Варинии и честолюбивого римского полководца Красса. Непреодолимая тяга к свободе заставляет Спартака поднять легендарное восстание рабов, ставшее важнейшей вехой мировой истории.', '0+', 80000000, 80000000, 1960, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'More titanic than any story ever told!', 197, '1960-06-01'),
  ('4ecc7ca9-2eb5-4d35-aba3-c926d04d74b1', 'Назад в будущее', 'Back to the Future', 'films/pic252.webp', 'posters/pic252.webp', 'Безумный ученый и 17-летний оболтус тестируют машину времени, наводя шороху в 1950-х. Классика кинофантастики', 'Подросток Марти с помощью машины времени, сооружённой его другом-профессором доком Брауном, попадает из 80-х в далекие 50-е. Там он встречается со своими будущими родителями, ещё подростками, и другом-профессором, совсем молодым.', '12+', 150000000, 75000000, 1985, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '7f2d3f26-fff8-fdfa-2ffb-1b1f9f5f71f3', 'Семнадцатилетний Марти МакФлай пришел вчера домой пораньше. На 30 лет раньше', 116, '1985-06-01'),
  ('fd287724-aff8-4f1b-b080-45d84a45bf99', 'Магнолия', 'Magnolia', 'films/pic253.webp', 'posters/pic253.webp', 'Судьбы нескольких человек удивительно переплетаются. Мощная полифоническая драма Пола Томаса Андерсона', 'Эта история произошла в долине Сан-Фернандо в дождливый день, когда на небе не было ни облачка. Благодаря вмешательству высших сил, а также нагромождению совпадений, случайностей, действий разных людей, их жизни и судьбы переплетутся и проникнут друг в друга в течение одного дня, финал которого будет незабываемым.', '18+', 300000000, 1500000000, 1999, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Безжалостная форма невероятных совпадений', 189, '1999-06-01'),
  ('56c63c8a-5066-457e-948c-47035aed0610', 'Золотая лихорадка', 'The Gold Rush', 'films/pic254.webp', 'posters/pic254.webp', 'История о злоключениях извечного любимца публики, маленького бродяги, который на этот раз отправляется на золотые прииски Аляски и как всегда порадует вас бесконечным калейдоскопом трюков и комических ситуаций.', 'История о злоключениях извечного любимца публики, маленького бродяги, который на этот раз отправляется на золотые прииски Аляски и как всегда порадует вас бесконечным калейдоскопом трюков и комических ситуаций.', '0+', 1000000, 3000000, 1925, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', '"The Picture I Want to Be Remembered by." -Charlie Chaplin. (Print Ad- Calgary Daily Herald, ((Calgary, Alta.)) 30 December 1925)', 95, '1925-06-01'),
  ('adf1c122-09ca-4f7e-a181-54a489989bc9', 'Отточенное лезвие', 'Sling Blade', 'films/pic255.webp', 'posters/pic255.webp', 'Вышедший из психлечебницы убийца сближается с матерью-одиночкой. Драма Билли Боба Торнтона, получившая «Оскар»', 'Карл после совершенного им жестокого преступления провел двадцать пять лет в сумасшедшем доме. Возвратившись в город своей молодости, в один из южных штатов Америки, он ведет себя спокойно и разумно. Это помогает ему найти работу и подружиться с мальчиком и его матерью-вдовой. Однако появление отвратительного и грубого любовника этой женщины ставит Карла перед мучительным выбором и ведет к резким переменам в жизни всех, вовлеченных в эту историю.', '18+', 1000000, 8000000, 1995, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Sometimes a hero comes from the most unlikely place.', 135, '1995-06-01'),
  ('e2d9a95c-97c6-4e6b-8ddb-50724205037b', 'Шарада', 'Charade', 'films/pic256.webp', 'posters/pic256.webp', 'После гибели мужа Регина узнает, что он украл крупную сумму денег. Детективная мелодрама с Одри Хепберн', 'Очаровательная американка Регги Ламберт, подав на развод, уезжает на курорт, где знакомится с привлекательным незнакомцем Питером Джошуа. По возвращении в Париж ее ждет ужасная новость: ее муж убит при загадочных обстоятельствах, а все семейные сбережения были сняты с банковского счета и исчезли в неизвестном направлении.

И вот в жизни героини во второй раз появляется ее недавний знакомый под другим именем, а за ним - целая толпа «однополчан» ее покойного супруга, жаждущих заполучить кругленькую сумму, которую ее благоверный украл во время Второй мировой войны. Все ее преследователи уверены, что она-то уж точно знает о местонахождении злосчастного наследства. 

По мере того как охотники за «военным трофеем» начинают погибать один за другим, Регине становится все сложней разобраться, кому она может доверять.', '18+', 300000000, 900000000, 1963, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Please don''t tell who did what to whom!', 113, '1963-06-01'),
  ('78525cff-a194-4903-b8e4-131f89d75ab5', 'Броненосец «Потемкин»', NULL, 'films/pic257.webp', 'posters/pic257.webp', 'Знаменитый матросский бунт, одно из значимых событий 1905 года. Великая драма, снятая на заре советского кино', 'Сюжет, основанный на подлинном историческом событии, образно выразил основные социальные тенденции ХХ века: массовое стремление к свободе, борьбу с тиранией, защиту человеческого достоинства, призыв к единению людей во имя  равноправия. Новаторская форма фильма и сегодня оказывает глубокое влияние на развитие выразительных средств кино.', '16+', 1000000, 500000, 1925, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a16', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Revolution is the only lawful, equal, effectual war. It was in Russia that this war was declared and begun.', 75, '1925-06-01'),
  ('4f845f56-5af4-4c64-8b9b-e7f654aa187c', 'История игрушек', 'Toy Story', 'films/pic258.webp', 'posters/pic258.webp', 'Игрушечные ковбой и космонавт соперничают за любовь своего человека. Новаторская и трогательная анимация Pixar', 'Игрушки Энди начинают жить своей жизнью, как только он выходит из комнаты. В день рождения мальчика царит паника — все боятся появления новой игрушки, которая перетянет внимание на себя. И только любимчик Энди, ковбой Вуди, ни о чем не переживает. Но когда мальчик получает в подарок астронавта Базза Лайтера, Вуди очень быстро оказывается забыт. И тогда ковбой решает вернуть себе первое место в сердце Энди.', '0+', 1000000, 5000000, 1995, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '1bd7cd20-f9f2-f7f4-fcf5-5f5f3f9f15f7', 'Proud to be a vegetable', 81, '1995-06-01'),
  ('092f8774-1563-49e8-9780-94598a2e15ff', 'Бразилия', 'Brazil', 'films/pic259.webp', 'posters/pic259.webp', 'Мелкий служащий попадает в тиски кошмарной бюрократии. Визуально богатая и смелая антиутопия Терри Гиллиама', 'Сэм Лоури вполне доволен жизнью. Он работает мелким служащим и согласен мириться с необустроенным бытом вопреки воле матери, входящей в элиту системы. Но внезапно он встречает девушку, которую постоянно видит в своих снах. Чтобы снова встретить её, он решается сменить работу.', '18+', 80000000, 640000000, 1985, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Suspicion breeds confidence', 132, '1985-06-01'),
  ('2f0aaf81-f3ff-4aa8-af25-fd0975a800ea', 'Приключения Робин Гуда', 'The Adventures of Robin Hood', 'films/pic260.webp', 'posters/pic260.webp', 'Пока король Ричард Львиное Сердце находится в крестовом походе, его брат принц Джон захватывает трон и начинает обирать собственный народ. Сэр Робин Локсли восстает против вероломного узурпатора и селится в Шервудском лесу. Заручившись поддержкой своих верных приспешников, он начинает грабить богатеев под сенью крон и раздавать их деньги беднякам.', 'Пока король Ричард Львиное Сердце находится в крестовом походе, его брат принц Джон захватывает трон и начинает обирать собственный народ. Сэр Робин Локсли восстает против вероломного узурпатора и селится в Шервудском лесу. Заручившись поддержкой своих верных приспешников, он начинает грабить богатеев под сенью крон и раздавать их деньги беднякам.', '12+', 300000000, 150000000, 1938, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'def389ec-f5f8-c3d0-f8f1-1f1bff5ed1f3', 'Excitement...Danger...Suspense...as this classic adventure story sweeps across the screen!', 98, '1938-06-01'),
  ('64f52eb4-c7e2-4270-8505-bbbb999e61cd', 'Житие Брайана по Монти Пайтон', 'Life of Brian', 'films/pic261.webp', 'posters/pic261.webp', 'Оказывается, 2000 лет назад волхвы слегка промахнулись и из-за небольшой астрономической ошибки явили, было, свои дары не тому новорожденному, которому следовало. Дитя звали Брайан, и он просто родился в тот же час и лишь домом дальше, чем Сами-Знаете-Кто. По причине сего инцидента потом все путали Брайана с Мессией, а ему было лень разубеждать своих поклонников.

Однако в почитании масс помимо приятной стороны есть и другая, и вот Брайан с тревогой обнаруживает себя в роли отчаянного религио...', 'Оказывается, 2000 лет назад волхвы слегка промахнулись и из-за небольшой астрономической ошибки явили, было, свои дары не тому новорожденному, которому следовало. Дитя звали Брайан, и он просто родился в тот же час и лишь домом дальше, чем Сами-Знаете-Кто. По причине сего инцидента потом все путали Брайана с Мессией, а ему было лень разубеждать своих поклонников.

Однако в почитании масс помимо приятной стороны есть и другая, и вот Брайан с тревогой обнаруживает себя в роли отчаянного религиозного лидера народного Фронта Иудеи, борющегося за свободу от римского ига - и в эпицентре больших неприятностей с оккупационными властями!…', '16+', 150000000, 750000000, 1979, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a18', 'adf056b9-c2f5-90ad-f5fe-ffe8fc2baff0', 'Just when you thought you were saved...', 94, '1979-06-01'),
  ('bd6068d7-7394-475b-981d-7369bc753bd6', 'Трамвай «Желание»', 'A Streetcar Named Desire', 'films/pic262.webp', 'posters/pic262.webp', 'Манерная Бланш гостит у сестры и ее мужа-работяги, который ей вовсе не рад. Драма, прославившая Марлона Брандо', 'Бланш Дюбуа приезжает в Новый Орлеан к беременной сестре Стелле, живущей с мужем Стэнли в местных трущобах. Бланш сообщает сестре, что разорена, ушла с работы и жить ей негде и не на что. Стэнли, воплощение естественности и грубости, сразу невзлюбил её за пристрастие к алкоголю и неуместное кокетство. Вскоре у Бланш появляется поклонник и призрачная надежда на замужество, но Стэнли расстраивает их помолвку.', '12+', 150000000, 750000000, 1951, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', '...When she got there she met the brute Stan, and the side of New Orleans she hardly knew existed', 122, '1951-06-01'),
  ('7445d8a3-6b6d-412e-b3d0-41f946c88512', 'Вечер в опере', 'A Night at the Opera', 'films/pic263.webp', 'posters/pic263.webp', 'Ловкач Отис Дрифтвуд придумал способ прикарманить денежки богатой вдовы, делами которой он управлял. Вдовушка спала и видела, как бы пробиться в высшее общество и Отис подговорил её вложить круглую сумму в нью-йоркскую оперу. Вместо прославленного тенора Ласпари Отис нанял певца из хора, а остальное присвоил. Певец оказался действительно хорош и за 10 долларов отработал на всю тысячу, а заодно покорил сердце любимой хористки.', 'Ловкач Отис Дрифтвуд придумал способ прикарманить денежки богатой вдовы, делами которой он управлял. Вдовушка спала и видела, как бы пробиться в высшее общество и Отис подговорил её вложить круглую сумму в нью-йоркскую оперу. Вместо прославленного тенора Ласпари Отис нанял певца из хора, а остальное присвоил. Певец оказался действительно хорош и за 10 долларов отработал на всю тысячу, а заодно покорил сердце любимой хористки.', '12+', 50000000, 50000000, 1935, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', 'adf056b9-c2f5-90ad-f5fe-ffe8fc2baff0', 'Don''t miss it! The funniest picture ever made!', 96, '1935-06-01'),
  ('d98d6b1a-6c9e-4c44-aa94-bbef9220bb8b', 'Свидетель обвинения', 'Witness for the Prosecution', 'films/pic265.webp', 'posters/pic265.webp', 'Сэр Уилфрид Робартс - тяжело больной адвокат, которому врачи запретили заниматься уголовными делами. Выполнить их рекомендации он смог только благодаря заботливой домашней медсестре мисс Плимсолл. Но когда его поверенный приводит к нему домой подозреваемого в убийстве Леонарда Воула, Робартс не может устоять и соглашается вести дело.', 'Сэр Уилфрид Робартс - тяжело больной адвокат, которому врачи запретили заниматься уголовными делами. Выполнить их рекомендации он смог только благодаря заботливой домашней медсестре мисс Плимсолл. Но когда его поверенный приводит к нему домой подозреваемого в убийстве Леонарда Воула, Робартс не может устоять и соглашается вести дело.', '12+', 300000000, 150000000, 1957, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Unmatched ...in a half century of motion picture suspense!', 116, '1957-06-01'),
  ('01957685-494c-4cf1-b6b1-6023fcdd73a2', 'Кто боится Вирджинии Вульф?', 'Who''s Afraid of Virginia Woolf?', 'films/pic266.webp', 'posters/pic266.webp', 'Два часа ночи в Новой Англии. Джордж — подавленный профессор истории, женатый на Марте, распутнице, чей отец является ректором колледжа, где преподает Джордж. После двадцати лет брака их союз постоянно скачет от любви к ненависти. Марта любит сравнивать своего слабого супруга со своим сильным отцом, зная, что это злит её мужа. Накануне вечером они отправились на вечеринку факультета, где познакомились с молодыми сотрудниками Ником и Хани. Ник, преподаватель биологии, считает себя сердцеедом, ...', 'Два часа ночи в Новой Англии. Джордж — подавленный профессор истории, женатый на Марте, распутнице, чей отец является ректором колледжа, где преподает Джордж. После двадцати лет брака их союз постоянно скачет от любви к ненависти. Марта любит сравнивать своего слабого супруга со своим сильным отцом, зная, что это злит её мужа. Накануне вечером они отправились на вечеринку факультета, где познакомились с молодыми сотрудниками Ником и Хани. Ник, преподаватель биологии, считает себя сердцеедом, а Хани, по определению Марты, серая мышка. Супружеская пара постарше приглашает вторую зайти в их комфортабельный дом и выпить по рюмочке на прощанье. Всю ночь напролёт они выпивают, танцуют и играют в психологические «игры».', '16+', 100000000, 800000000, 1966, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'It can now be said: 1. Apart from its widespread critical acclaim, it has provoked more discussion, interest and excitement than any other picture in memory. 2. People want to see it - in unprecedente', 131, '1966-06-01'),
  ('5e9d1949-484b-4fc5-93b6-5af24e3470ed', 'Изгоняющий дьявола', 'The Exorcist', 'films/pic267.webp', 'posters/pic267.webp', 'Странный недуг поражает дочь известной актрисы. Классика ужасов, первый фильм, посвященный экзорцизму', 'В семью известной актрисы приходит беда — её несовершеннолетняя дочь начинает вести себя неадекватным образом. Мать полагает, что это следствие её личной трагедии, врачи подозревают психическое заболевание, но не могут поставить диагноз. Специально приглашенный священник подозревает, что девочка одержима дьяволом.', '18+', 50000000, 400000000, 1973, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '6f1c2f25-fef7-fcf9-1ffa-0a0f8f4f60f2', 'Самый страшный фильм всех времен', 122, '1973-06-01'),
  ('fd282134-5338-4f45-aa17-02c41d233371', 'Человек, который застрелил Либерти Вэланса', 'The Man Who Shot Liberty Valance', 'films/pic268.webp', 'posters/pic268.webp', 'Сенатор Рэйнс Стоддард возвращается в город Шинбон на Диком Западе, чтобы присутствовать на похоронах своего друга, Тома Донифона. Журналисту, который расспрашивает его о причине визита, сенатор рассказывает историю о том, как начиналась его карьера — карьера человека, который застрелил Либерти Вэланса.', 'Сенатор Рэйнс Стоддард возвращается в город Шинбон на Диком Западе, чтобы присутствовать на похоронах своего друга, Тома Донифона. Журналисту, который расспрашивает его о причине визита, сенатор рассказывает историю о том, как начиналась его карьера — карьера человека, который застрелил Либерти Вэланса.', '12+', 300000000, 150000000, 1962, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'Two Great Stars Appear Together For the First Time!', 123, '1962-06-01'),
  ('3b579622-a216-4b19-9383-24c77154629f', 'Вся президентская рать', 'All the President''s Men', 'films/pic269.webp', 'posters/pic269.webp', 'Честный чиновник встает на путь коррупции и искушений. Политический триллер по резонансному делу, 4 «Оскара»', 'Июнь 1972 года, Вашингтон. Ночью в штаб-квартире Национального комитета Демократической партии полицейские арестовывают группу лиц, которые тайно проникли в помещение, имея при себе подслушивающую аппаратуру. Журналисты газеты The Washington Post Боб Вудворд и Карл Бернстин начинают собственное расследование, и вскоре выясняется, что нити преступления ведут в Белый дом.', '18+', 80000000, 160000000, 1976, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '8bdf34f7-afe3-7e8b-f3fc-dfe6fa098ef8', 'The most devastating detective story of the century!', 138, '1976-06-01'),
  ('e597e6dd-2045-4a9c-a148-29513907dab7', 'Другие', 'The Others', 'films/pic270.webp', 'posters/pic270.webp', 'Дочка Грейс утверждает, что видит призраков в мрачном особняке. Первоклассный ретрохоррор с Николь Кидман', 'Грейс прячет своих детей в уединенном особняке на острове, где семейство дожидается окончания Второй мировой войны. Войны, с которой должен вернуться муж Грейс.

Её дочь и сын страдают странным заболеванием, они не выносят прямого дневного света. Когда в доме появляются трое новых слуг, им приходится соблюдать правила: все комнаты всегда должны быть в полумраке, и нельзя открывать дверь, пока не заперта предыдущая. Но мерному течению жизни дома вскоре приходит конец - некая потусторонняя сущность пытается нарушить заведённый порядок.', '18+', 100000000, 50000000, 2001, 'a0eebc77-7c0b-4ef6-bb6d-6bb9bd360a12', '5f0b1f24-fdf6-fbf8-0ff9-9f9f7f3f59f1', 'Рано или поздно они найдут тебя...', 101, '2001-06-01')
ON CONFLICT (title, year) DO NOTHING;

