AND NOT EXISTS (
  SELECT 1 FROM actor_in_film aif
  WHERE aif.actor_id = t.actor_id
    AND aif.film_id = t.film_id
);

COMMIT;

INSERT INTO film_feedback (user_id, film_id, title, text, rating)
SELECT 
    user_id::uuid,
    'e4482ab6-9f0e-4da7-989a-e8466ed3dbba'::uuid,
    title,
    text,
    rating
FROM (VALUES
    ('a1b2c3d4-e5f6-7890-abcd-ef1234567890', 'Классика Куросавы', 'Великий фильм от мастера японского кино.', 10),
    ('b2c3d4e5-f6a7-8901-bcde-f23456789012', 'Умный самурай', 'Потрясающая смекалка главного героя.', 9),
    ('c3d4e5f6-a7b8-9012-cdef-345678901234', 'Черный юмор', 'Идеальное сочетание действия и сатиры.', 8),
    ('d4e5f6a7-b8c9-0123-def4-456789012345', 'Влияние на вестерны', 'Вижу корни "За пригоршню долларов".', 9),
    ('e5f6a7b8-c9d0-1234-ef56-567890123456', 'Атмосферный нуар', 'Отличная работа с тенью и светом.', 8)
) AS vals(user_id, title, text, rating)
WHERE EXISTS (SELECT 1 FROM film WHERE id = 'e4482ab6-9f0e-4da7-989a-e8466ed3dbba');

